/* @lc app=leetcode id=3381 lang=kotlin */ class Solution { fun maxSubarraySum(nums: IntArray, k: Int): Long = nums.runningFold(0L) { a, b -> a + b }.let { pre -> LongArray(k) { Long.MAX_VALUE / 2 }.let { mn -> pre.indices.fold(Long.MIN_VALUE) { best, j -> (j % k).let { r -> (if (mn[r] < Long.MAX_VALUE / 2) maxOf(best, pre[j] - mn[r]) else best).also { mn[r] = minOf(mn[r], pre[j]) } } } } } }